import{_ as t,o,c as n,a4 as s}from"./chunks/framework.ClGzHnIj.js";const m=JSON.parse('{"title":"Labo de décision","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://lognebudo.github.io/llmxray/docs/fr/guide/decision-lab.html"}]]},"headers":[],"relativePath":"fr/guide/decision-lab.md","filePath":"fr/guide/decision-lab.md","lastUpdated":1791749853000}'),a={name:"fr/guide/decision-lab.md"};function i(r,e,l,d,u,c){return o(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="labo-de-decision" tabindex="-1">Labo de décision <a class="header-anchor" href="#labo-de-decision" aria-label="Permalink to &quot;Labo de décision&quot;">​</a></h1><p>Le <strong>Labo de décision</strong> pose à un modèle de décision des questions typées sur une situation et montre la probabilité derrière chaque réponse.</p><p><strong>Élément de la barre latérale :</strong> Labo de décision (sous le Labo de cache) <strong>Route :</strong> <code>/decision-lab</code><strong>Ajouté dans :</strong> v0.7.0 (octobre 2026) <strong>Nécessite :</strong> Ollama 0.35.1 ou plus récent, et un modèle de décision (<code>nimble</code>, <code>tev1</code>, <code>clef-flash</code> ou <code>clef</code>)</p><h2 id="a-quoi-ca-sert" tabindex="-1">À quoi ça sert ? <a class="header-anchor" href="#a-quoi-ca-sert" aria-label="Permalink to &quot;À quoi ça sert ?&quot;">​</a></h2><p>Un modèle de décision n’écrit pas de texte. Vous lui donnez un <strong>état</strong> (un ticket, un message, une ligne de log, un document) et une ou plusieurs <strong>questions</strong>, et il renvoie :</p><table tabindex="0"><thead><tr><th>Type de question</th><th>Ce qui revient</th></tr></thead><tbody><tr><td><strong>Choix</strong></td><td>Le candidat retenu, une probabilité pour <em>chaque</em> candidat, et une confiance</td></tr><tr><td><strong>Probabilité oui / non</strong></td><td>Une seule probabilité que la condition soit vraie</td></tr><tr><td><strong>Score sur une échelle</strong></td><td>La position attendue sur votre échelle ordonnée, une probabilité par échelon, et une confiance</td></tr></tbody></table><p>Les probabilités sont la distribution de sortie du modèle lui-même sur les candidats, pas un nombre extrait d’une phrase. C’est ce qui les rend intéressantes : un modèle de chat à qui l’on demande « est-ce urgent ? » répond <em>oui</em> ; un modèle de décision répond <em>0,99</em>, et pour un ticket limite il répond <em>0,55</em>, et la différence se voit.</p><p>Ollama sert ces modèles sur <code>/v1/systemone</code> (ajouté en 0.35.1). Ils déclarent <code>decision</code> comme <strong>seule</strong> capacité, donc LLMxRay les tient à l’écart de tous les sélecteurs de chat et de plongements et les liste ici. Leur envoyer une requête de chat n’échoue pas proprement : ils répondent par des fragments de leur propre schéma, ce qui est précisément la raison d’être du filtre.</p><h2 id="utiliser-la-page" tabindex="-1">Utiliser la page <a class="header-anchor" href="#utiliser-la-page" aria-label="Permalink to &quot;Utiliser la page&quot;">​</a></h2><ol><li>Choisissez un modèle de décision. S’il n’y en a aucun, téléchargez-en un depuis la page Modèles ; <code>tev1:0.8b</code> est le plus petit.</li><li>Décrivez l’<strong>état</strong>. Toutes les questions portent sur ce seul texte.</li><li>Éditez les <strong>questions</strong>. Chacune a une clé de réponse (sous laquelle le résultat revient), un type, une consigne, et pour les types choix et score une liste de candidats : <ul><li><strong>Choix</strong> : un par ligne sous la forme <code>nom : description</code>.</li><li><strong>Score</strong> : un par ligne, du plus bas au plus haut. L’ordre <em>est</em> l’échelle.</li><li>Ollama accepte de 2 à 26 candidats et de 1 à 64 questions par requête ; la page vous le dit avant l’envoi quand une question sort de ces bornes.</li></ul></li><li><strong>Décider</strong>. Les réponses apparaissent à droite sous forme de barres, le candidat retenu mis en évidence, avec les nombres de tokens en entrée et en sortie et le temps d’aller-retour.</li></ol><p>La page s’ouvre sur un exemple complet : un ticket de support interrogé de trois façons, une question de chaque type. C’est la requête qui a été exécutée en direct lors de la vérification d’Ollama 0.40.3.</p><h2 id="lire-les-reponses" tabindex="-1">Lire les réponses <a class="header-anchor" href="#lire-les-reponses" aria-label="Permalink to &quot;Lire les réponses&quot;">​</a></h2><ul><li><strong>Choix</strong> : les barres sont triées par probabilité. Celle mise en évidence est le choix du modèle. La confiance est le chiffre du modèle lui-même, rapporté à côté.</li><li><strong>Oui / non</strong> : affiché comme une barre <em>oui</em> et une barre <em>non</em> dont la somme fait 1.</li><li><strong>Score</strong> : les barres restent dans l’ordre de l’échelle, parce que la position est le sens. L’échelon mis en évidence est le plus probable. Le nombre <em>score</em> est la position attendue (pondérée par les probabilités), il peut donc tomber entre deux échelons : 2,37 sur une échelle à quatre échelons veut dire « majeur, penchant vers panne totale ».</li></ul><h2 id="ce-que-la-page-ne-fait-pas" tabindex="-1">Ce que la page ne fait pas <a class="header-anchor" href="#ce-que-la-page-ne-fait-pas" aria-label="Permalink to &quot;Ce que la page ne fait pas&quot;">​</a></h2><p>Elle ne diffuse pas en flux (l’endpoint ne le fait jamais), ne conserve pas d’historique, et n’envoie pas encore d’images, bien que <code>clef</code> et <code>clef-flash</code> en acceptent. C’est un observatoire de ce qu’un modèle de décision renvoie réellement, rien de plus.</p>',15)])])}const h=t(a,[["render",i]]);export{m as __pageData,h as default};
